; Epoch sound driver -- Doraemon (J)
; ROM bank $07, $4000-$5AB5. Assembles byte-identical with RGBDS 1.0.
; Generated by tools/epoch_gen.py. No macros: data is plain db/dw with a
; comment on each row. See Epoch_SoundDriver.md for the format.

INCLUDE "epoch_sound.inc"

DEF SND_RAM EQU $C700
DEF TRK_SIZE EQU $1E

; driver RAM
DEF wSndMusicId       EQU $C700
DEF wSndSfxId         EQU $C701
DEF wSndMusicTracks   EQU $C702
DEF wSndSfxTracks     EQU $C703
DEF wSndMusicTempo    EQU $C704
DEF wSndSfxTempo      EQU $C705
DEF wSndPan           EQU $C706
DEF wSndPanFlag       EQU $C707
DEF wSndTrackIndex    EQU $C708
DEF wSndRowByte       EQU $C7BD
DEF wSndMusicLengths  EQU $C7C5
DEF wSndSfxLengths    EQU $C7C7
DEF wSndCh1           EQU $C709  ; music track struct
DEF wSndCh2           EQU $C727  ; music track struct
DEF wSndCh3           EQU $C745  ; music track struct
DEF wSndCh4           EQU $C763  ; music track struct
DEF wSndSfxCh1        EQU $C781  ; SFX track struct
DEF wSndSfxCh4        EQU $C79F  ; SFX track struct

SECTION "Epoch sound", ROMX[$4000], BANK[$7]


; Entry points (jump table at the start of the driver).
; The game calls Sound_Output, then Sound_Update, once per frame.
Sound_Update::
    jp SndUpdate                            ; $4000  once per frame, after SndOutput
Sound_Output::
    jp SndOutput                            ; $4003  once per frame
Sound_Init::
    jp SndInit                              ; $4006  boot
Sound_PlayMusic::
    jp SndPlayMusic                         ; $4009  a = music id
Sound_PlaySfx::
    jp SndPlaySfx                           ; $400C  a = SFX id
Sound_StopMusic::
    jp SndStopMusic                         ; $400F
Sound_StopSfx::
    jp SndStopSfx                           ; $4012

; SndInit: APU on, master volume max, all channels on both sides,
; loads the fixed wave and stops everything.
SndInit:
    ld a,$00                                ; $4015
    ldh [rNR30],a                           ; $4017
    ld a,$20                                ; $4019
    ldh [rNR32],a                           ; $401B
    ld a,$77                                ; $401D
    ldh [rNR50],a                           ; $401F
    ld a,$FF                                ; $4021
    ldh [rNR51],a                           ; $4023
    ldh [rNR52],a                           ; $4025
    ld [wSndPan],a                          ; $4027
    call SndLoadWave                        ; $402A
    call Sound_StopMusic                    ; $402D
    jp Sound_StopSfx                        ; $4030

; Copies the 16-byte SndWave into wave RAM. This is the only wave the
; driver ever uses.
SndLoadWave:
    ld hl,SndWave                           ; $4033
    ld c,$30                                ; $4036
    ld b,$10                                ; $4038
.l403A
    ld a,[hli]                              ; $403A
    ldh [c],a                               ; $403B
    inc c                                   ; $403C
    dec b                                   ; $403D
    jr nz,.l403A                            ; $403E
    ret                                     ; $4040

; the only wave: a fixed, roughly sine-like shape
SndWave:
    db $CE, $FE, $B8, $BE, $FF, $FF, $FE, $B9
    db $63, $10, $00, $00, $00, $00, $13, $69


; SndPlayMusic: a = music id.
; Header: tempo (1 byte), length table (word), then 4 track pointers
; (ch1, ch2, ch3, ch4). A null pointer means the channel is unused.
SndPlayMusic:
    ld [wSndMusicId],a                      ; $4051
    ld de,MusicTable                        ; $4054
    sla a                                   ; $4057
    add a,e                                 ; $4059
    ld e,a                                  ; $405A
    ld a,d                                  ; $405B
    adc a,$00                               ; $405C
    ld d,a                                  ; $405E
    ld a,[de]                               ; $405F
    ld l,a                                  ; $4060
    inc de                                  ; $4061
    ld a,[de]                               ; $4062
    ld h,a                                  ; $4063
    ld a,$00                                ; $4064
    ldh [rNR30],a                           ; $4066
    ld a,$05                                ; $4068  dead load
    ld a,$04                                ; $406A  active music tracks
    ld [wSndMusicTracks],a                  ; $406C
    ld a,[hli]                              ; $406F
    ld [wSndMusicTempo],a                   ; $4070
    ld a,[hli]                              ; $4073
    ld [$C7C1],a                            ; $4074
    ld a,[hli]                              ; $4077
    ld [$C7C2],a                            ; $4078
    ld de,wSndCh1                           ; $407B
    ld c,$04                                ; $407E
.trackLoop
    ld a,$01                                ; $4080  TRK_STATUS = 1
    ld [de],a                               ; $4082
    inc de                                  ; $4083  TRK_PTR
    ld a,[hli]                              ; $4084
    ld [de],a                               ; $4085
    ld b,a                                  ; $4086
    inc de                                  ; $4087
    ld a,[hli]                              ; $4088
    ld [de],a                               ; $4089
    or b                                    ; $408A
    jr z,.noTrack                           ; $408B
    inc e                                   ; $408D  TRK_COUNT = 0
    ld a,$00                                ; $408E
    ld [de],a                               ; $4090
    inc e                                   ; $4091
    ld [de],a                               ; $4092
    ld a,e                                  ; $4093  TRK_LOOPDEPTH = 0
    add a,$0D                               ; $4094
    ld e,a                                  ; $4096
    ld a,$00                                ; $4097
    ld [de],a                               ; $4099
    ld a,e                                  ; $409A
    add a,$0D                               ; $409B
    ld e,a                                  ; $409D
.l409E
    dec c                                   ; $409E
    jr nz,.trackLoop                        ; $409F
    ret                                     ; $40A1
.noTrack
    dec e                                   ; $40A2
    dec e                                   ; $40A3
    ld a,$04                                ; $40A4  status 4: silenced and counted down by SndOutput
    ld [de],a                               ; $40A6
    ld a,e                                  ; $40A7
    add a,$1E                               ; $40A8
    ld e,a                                  ; $40AA
    jr .l409E                               ; $40AB

; SndPlaySfx: a = SFX id.
; Header: tempo, length table, then 2 track pointers. The first runs on
; hardware ch1 (tone), the second on ch4 (noise).
SndPlaySfx:
    ld [wSndSfxId],a                        ; $40AD
    ld de,SfxTable                          ; $40B0
    sla a                                   ; $40B3
    add a,e                                 ; $40B5
    ld e,a                                  ; $40B6
    ld a,d                                  ; $40B7
    adc a,$00                               ; $40B8
    ld d,a                                  ; $40BA
    ld a,[de]                               ; $40BB
    ld l,a                                  ; $40BC
    inc de                                  ; $40BD
    ld a,[de]                               ; $40BE
    ld h,a                                  ; $40BF
    ld a,$02                                ; $40C0
    ld [wSndSfxTracks],a                    ; $40C2
    ld a,[hli]                              ; $40C5
    ld [wSndSfxTempo],a                     ; $40C6
    ld a,[hli]                              ; $40C9
    ld [$C7C3],a                            ; $40CA
    ld a,[hli]                              ; $40CD
    ld [$C7C4],a                            ; $40CE
    ld de,wSndSfxCh1                        ; $40D1
    ld c,$02                                ; $40D4
.trackLoop
    ld a,$01                                ; $40D6  TRK_STATUS = 1
    ld [de],a                               ; $40D8
    inc de                                  ; $40D9  TRK_PTR
    ld a,[hli]                              ; $40DA
    ld [de],a                               ; $40DB
    ld b,a                                  ; $40DC
    inc de                                  ; $40DD
    ld a,[hli]                              ; $40DE
    ld [de],a                               ; $40DF
    or b                                    ; $40E0
    jr z,.noTrack                           ; $40E1
    inc de                                  ; $40E3  TRK_COUNT = 0
    ld a,$00                                ; $40E4
    ld [de],a                               ; $40E6
    inc de                                  ; $40E7
    ld [de],a                               ; $40E8
    ld a,e                                  ; $40E9  TRK_LOOPDEPTH = 0
    add a,$0D                               ; $40EA
    ld e,a                                  ; $40EC
    ld a,$00                                ; $40ED
    ld [de],a                               ; $40EF
    ld a,e                                  ; $40F0
    add a,$0D                               ; $40F1
    ld e,a                                  ; $40F3
    dec c                                   ; $40F4
    jr nz,.trackLoop                        ; $40F5
    jr .done                                ; $40F7
.noTrack
    dec e                                   ; $40F9
    dec e                                   ; $40FA
    ld a,$04                                ; $40FB
    ld [de],a                               ; $40FD
    ld a,e                                  ; $40FE
    add a,$1E                               ; $40FF
    ld e,a                                  ; $4101
    dec c                                   ; $4102
    jr nz,.trackLoop                        ; $4103
.done
    ld a,$02                                ; $4105  2 = SFX just started (SndUpdate turns it into 1)
    ld [wSndPanFlag],a                      ; $4107
    ret                                     ; $410A

; SndStopMusic: marks all 4 music tracks "ending" (status 4). The next
; SndOutput silences them.
SndStopMusic:
    ld a,$04                                ; $410B
    ld [wSndMusicTracks],a                  ; $410D
    ld [wSndCh1],a                          ; $4110
    ld [wSndCh2],a                          ; $4113
    ld [wSndCh3],a                          ; $4116
    ld [wSndCh4],a                          ; $4119
    ret                                     ; $411C

; SndStopSfx: same for the 2 SFX tracks.
SndStopSfx:
    ld a,$02                                ; $411D
    ld [wSndSfxTracks],a                    ; $411F
    ld a,$04                                ; $4122
    ld [wSndSfxCh1],a                       ; $4124
    ld [wSndSfxCh4],a                       ; $4127
    ret                                     ; $412A

; SndUpdate: the sequencer tick. Runs the 6 tracks in order
; (music ch1-ch4, SFX ch1, SFX ch4).
; Each track: counter -= tempo. While it has not underflowed, only the
; instrument envelope runs. When it underflows, rows are parsed until
; the next note/rest/tie.
SndUpdate:
    ld a,[wSndPanFlag]                      ; $412B  2 = SFX just started
    cp $02                                  ; $412E
    jr nz,.go                               ; $4130
    ld a,$01                                ; $4132
    ld [wSndPanFlag],a                      ; $4134
.go
    ld hl,wSndCh1                           ; $4137
    ld a,$00                                ; $413A
    ld [wSndTrackIndex],a                   ; $413C

; hl = track struct
SndTrackLoop:
    push hl                                 ; $413F
    ld a,[hli]                              ; $4140
    and $03                                 ; $4141
    jp z,SndNextTrack                       ; $4143
    ld c,a                                  ; $4146
    ld a,[hli]                              ; $4147
    ld e,a                                  ; $4148
    ld a,[hli]                              ; $4149
    ld d,a                                  ; $414A
    ld a,[wSndTrackIndex]                   ; $414B
    cp $04                                  ; $414E  tracks 4/5 are SFX
    jr nc,.l4157                            ; $4150
    ld a,[wSndMusicTempo]                   ; $4152
    jr .l415A                               ; $4155
.l4157
    ld a,[wSndSfxTempo]                     ; $4157
.l415A
    ld b,a                                  ; $415A
    ld a,[hl]                               ; $415B
    sub b                                   ; $415C
    ld [hli],a                              ; $415D
    ld a,[hl]                               ; $415E
    sbc a,$00                               ; $415F
    ld [hli],a                              ; $4161
    jp nc,SndTrackEnvelope                  ; $4162

; de = data pointer, hl = TRK_NOTE, track struct on the stack.
SndParse:
    ld a,[de]                               ; $4165
    cp $F0                                  ; $4166
    jp nz,SndParseRow                       ; $4168
; $F0 nn: instrument. Ignored on noise tracks (ch4 / SFX ch4).
; Copies 5 register bytes to TRK_NR0..TRK_NR4 and the mode byte,
; then mode-specific parameters.
.instrument
    inc de                                  ; $416B
    ld a,[de]                               ; $416C
    inc de                                  ; $416D
    sla a                                   ; $416E
    push de                                 ; $4170
    push hl                                 ; $4171
    ld hl,InstTable                         ; $4172
    add a,l                                 ; $4175
    ld l,a                                  ; $4176
    ld a,$00                                ; $4177
    adc a,h                                 ; $4179
    ld h,a                                  ; $417A
    ld a,[wSndTrackIndex]                   ; $417B
    cp $03                                  ; $417E  noise tracks ignore instruments
    jr z,.instDone                          ; $4180
    cp $05                                  ; $4182
    jr z,.instDone                          ; $4184
    ld a,[hli]                              ; $4186
    ld e,a                                  ; $4187
    ld a,[hl]                               ; $4188
    ld d,a                                  ; $4189
    pop hl                                  ; $418A
    push hl                                 ; $418B
    inc l                                   ; $418C
    ld c,$05                                ; $418D
.l418F
    ld a,[de]                               ; $418F
    inc de                                  ; $4190
    ld [hli],a                              ; $4191
    dec c                                   ; $4192
    jr nz,.l418F                            ; $4193
    ld a,[de]                               ; $4195
    ld [hli],a                              ; $4196
    and a                                   ; $4197
    jr z,.instDone                          ; $4198
    ; mode 1: volume steps. TRK_ENVPARAM = TRK_ENVCOUNT = rate,
    ; TRK_ENVPTR = address of the step list, TRK_ENVINDEX = 0.
    cp $01                                  ; $419A
    jr nz,.notMode1                         ; $419C
    inc de                                  ; $419E
    ld a,[de]                               ; $419F
    ld [hli],a                              ; $41A0
    ld [hli],a                              ; $41A1
    inc de                                  ; $41A2
    ld a,e                                  ; $41A3
    ld [hli],a                              ; $41A4
    ld a,d                                  ; $41A5
    ld [hli],a                              ; $41A6
    ld a,$00                                ; $41A7
    ld [hl],a                               ; $41A9
    pop hl                                  ; $41AA
    pop de                                  ; $41AB
    jp SndParse                             ; $41AC
; mode 2: TRK_ENVPARAM = TRK_ENVCOUNT = frames (broken, see SndTrackEnvelope)
.notMode1
    cp $02                                  ; $41AF
    jr nz,.gateMode                         ; $41B1
    inc de                                  ; $41B3
    ld a,[de]                               ; $41B4
    ld [hli],a                              ; $41B5
    ld [hli],a                              ; $41B6
    jr .instDone                            ; $41B7
; mode 3 and up: TRK_ENVPARAM = n * current tempo (gate, in counter units).
.gateMode
    inc de                                  ; $41B9
    ld a,[de]                               ; $41BA
    ld c,a                                  ; $41BB
    ld a,[wSndTrackIndex]                   ; $41BC
    cp $04                                  ; $41BF
    jr nc,.l41C8                            ; $41C1
    ld a,[wSndMusicTempo]                   ; $41C3
    jr .l41CB                               ; $41C6
.l41C8
    ld a,[wSndSfxTempo]                     ; $41C8
.l41CB
    ld b,a                                  ; $41CB
    ld a,$00                                ; $41CC
    ld d,a                                  ; $41CE
.l41CF
    add a,b                                 ; $41CF
    jr nc,.l41D3                            ; $41D0
    inc d                                   ; $41D2
.l41D3
    dec c                                   ; $41D3
    jr nz,.l41CF                            ; $41D4
    ld [hli],a                              ; $41D6
    ld a,d                                  ; $41D7
    ld [hl],a                               ; $41D8
    jr .instDone                            ; $41D9
.instDone
    pop hl                                  ; $41DB
    pop de                                  ; $41DC
    jp SndParse                             ; $41DD

; Row byte < $E0: hi nibble = length, lo nibble = pitch.
; hi nibble 0-C: length = lengths[hi] (song length table).
; hi nibble D:   length = next 2 bytes (little-endian).
SndParseRow:
    cp $E0                                  ; $41E0
    jp nc,SndParseCmd                       ; $41E2
    ld [wSndRowByte],a                      ; $41E5
    and $F0                                 ; $41E8
    cp $D0                                  ; $41EA
    jr nz,.tableLength                      ; $41EC
    inc de                                  ; $41EE
    ld a,[de]                               ; $41EF
    ld c,a                                  ; $41F0
    inc de                                  ; $41F1
    ld a,[de]                               ; $41F2
    ld b,a                                  ; $41F3
    jr .addLength                           ; $41F4
.tableLength
    push hl                                 ; $41F6
    ld a,[wSndTrackIndex]                   ; $41F7
    cp $04                                  ; $41FA
    jr nc,.l4207                            ; $41FC
    ld a,[$C7C1]                            ; $41FE
    ld l,a                                  ; $4201
    ld a,[$C7C2]                            ; $4202
    jr .l420E                               ; $4205
.l4207
    ld a,[$C7C3]                            ; $4207
    ld l,a                                  ; $420A
    ld a,[$C7C4]                            ; $420B
.l420E
    ld h,a                                  ; $420E
    ld a,[de]                               ; $420F
    and $F0                                 ; $4210
    srl a                                   ; $4212
    srl a                                   ; $4214
    srl a                                   ; $4216
    add a,l                                 ; $4218
    ld l,a                                  ; $4219
    jr nc,.l421D                            ; $421A
    inc h                                   ; $421C
.l421D
    ld a,[hli]                              ; $421D
    ld c,a                                  ; $421E
    ld a,[hl]                               ; $421F
    ld b,a                                  ; $4220
    pop hl                                  ; $4221
; counter += length * 8
.addLength
    sla c                                   ; $4222
    rl b                                    ; $4224
    sla c                                   ; $4226
    rl b                                    ; $4228
    sla c                                   ; $422A
    rl b                                    ; $422C
    dec l                                   ; $422E
    dec l                                   ; $422F
    ld a,[hl]                               ; $4230
    add a,c                                 ; $4231
    ld [hli],a                              ; $4232
    ld a,[hl]                               ; $4233
    adc a,b                                 ; $4234
    ld [hli],a                              ; $4235
    ; lo nibble: 9 = tie (keep sounding, status unchanged), 8 = rest,
    ; 6 = absolute note in the next byte, 0-5/7 = note + n, A-F = note - (16-n).
    ld a,[wSndRowByte]                      ; $4236
    and $0F                                 ; $4239
    cp $09                                  ; $423B
    jr nz,.notTie                           ; $423D
    inc de                                  ; $423F
    pop hl                                  ; $4240
    inc hl                                  ; $4241
    jp .savePtr                             ; $4242  tie: only the pointer is saved
.notTie
    cp $08                                  ; $4245
    jr z,.rest                              ; $4247
    cp $06                                  ; $4249
    jr nz,.relative                         ; $424B
    inc de                                  ; $424D
    ld a,[de]                               ; $424E
    jr .setNote                             ; $424F
.relative
    cp $08                                  ; $4251
    jr c,.l4257                             ; $4253
    or $F0                                  ; $4255
.l4257
    add a,[hl]                              ; $4257
.setNote
    ld [hli],a                              ; $4258
    ld b,a                                  ; $4259
    ld a,[wSndTrackIndex]                   ; $425A
    cp $03                                  ; $425D
    jr z,.drumMusic                         ; $425F
    cp $05                                  ; $4261
    jr z,.drumSfx                           ; $4263
; tone channels: frequency = FreqTable[note - $10]. Only the low 3 bits
; of TRK_NR4 are replaced, so the instrument keeps its trigger/length bits.
.toneNote
    ld a,b                                  ; $4265
    sla a                                   ; $4266
    ld bc,FreqTable - $20                   ; $4268
    add a,c                                 ; $426B
    ld c,a                                  ; $426C
    ld a,b                                  ; $426D
    adc a,$00                               ; $426E
    ld b,a                                  ; $4270
    inc l                                   ; $4271
    inc l                                   ; $4272
    inc l                                   ; $4273
    ld a,[bc]                               ; $4274
    ld [hli],a                              ; $4275
    inc bc                                  ; $4276
    ld a,[bc]                               ; $4277
    and $07                                 ; $4278
    ld b,a                                  ; $427A
    ld a,[hl]                               ; $427B
    and $F8                                 ; $427C
    or b                                    ; $427E
    ld [hli],a                              ; $427F
    ; note start for the instrument mode
    ld a,[hli]                              ; $4280
    and a                                   ; $4281
    jp z,.keyOn                             ; $4282
    cp $02                                  ; $4285
    jr nc,.notMode1                         ; $4287
    ; mode 1: restart the step counter and load step 0 as NRx2 volume
    ld a,[hli]                              ; $4289
    ld [hli],a                              ; $428A
    push de                                 ; $428B
    ld a,[hli]                              ; $428C
    ld e,a                                  ; $428D
    ld a,[hli]                              ; $428E
    ld d,a                                  ; $428F
    ld a,[de]                               ; $4290
    ld b,a                                  ; $4291
    ld a,$00                                ; $4292
    ld [hl],a                               ; $4294
    ld a,l                                  ; $4295
    sub $08                                 ; $4296
    ld l,a                                  ; $4298
    ld a,[hl]                               ; $4299
    and $0F                                 ; $429A
    swap b                                  ; $429C
    or b                                    ; $429E
    ld [hl],a                               ; $429F
    pop de                                  ; $42A0
    jp .keyOn                               ; $42A1
.notMode1
    jr nz,.gate                             ; $42A4
    ld a,[hli]                              ; $42A6
    ld [hli],a                              ; $42A7
    jp .keyOn                               ; $42A8
; mode 3: TRK_ENVPTR (used as a word here) = counter - gate.
.gate
    push hl                                 ; $42AB
    ld a,l                                  ; $42AC
    sub $09                                 ; $42AD
    ld l,a                                  ; $42AF
    ld a,[hli]                              ; $42B0
    ld c,a                                  ; $42B1
    ld a,[hl]                               ; $42B2
    ld b,a                                  ; $42B3
    pop hl                                  ; $42B4
    ld a,c                                  ; $42B5
    sub [hl]                                ; $42B6
    ld c,a                                  ; $42B7
    inc l                                   ; $42B8
    ld a,b                                  ; $42B9
    sbc a,[hl]                              ; $42BA
    ld b,a                                  ; $42BB
    inc l                                   ; $42BC
    ld a,c                                  ; $42BD
    ld [hli],a                              ; $42BE
    ld a,b                                  ; $42BF
    ld [hl],a                               ; $42C0
    jp .keyOn                               ; $42C1
; rest: status 5 = release
.rest
    ld a,$05                                ; $42C4
    jp .setStatus                           ; $42C6
; noise tracks: NR41-NR44 from DrumTable[note - $34]
.drumMusic
    ld hl,DrumTable                         ; $42C9
    ld a,b                                  ; $42CC
    sub $34                                 ; $42CD
    sla a                                   ; $42CF
    sla a                                   ; $42D1
    add a,l                                 ; $42D3
    ld l,a                                  ; $42D4
    jr nc,.l42D8                            ; $42D5
    inc h                                   ; $42D7
.l42D8
    ld bc,wSndCh4 + TRK_NR1                 ; $42D8
    jr .copyDrum                            ; $42DB
.drumSfx
    ld hl,DrumTable                         ; $42DD
    ld a,b                                  ; $42E0
    sub $34                                 ; $42E1
    sla a                                   ; $42E3
    sla a                                   ; $42E5
    add a,l                                 ; $42E7
    ld l,a                                  ; $42E8
    jr nc,.l42EC                            ; $42E9
    inc h                                   ; $42EB
.l42EC
    ld bc,wSndSfxCh4 + TRK_NR1              ; $42EC
.copyDrum
    ld a,[hli]                              ; $42EF
    ld [bc],a                               ; $42F0
    inc bc                                  ; $42F1
    ld a,[hli]                              ; $42F2
    ld [bc],a                               ; $42F3
    inc bc                                  ; $42F4
    ld a,[hli]                              ; $42F5
    ld [bc],a                               ; $42F6
    inc bc                                  ; $42F7
    ld a,[hli]                              ; $42F8
    ld [bc],a                               ; $42F9
; status 6 = key on (full register write in SndOutput)
.keyOn
    ld a,$06                                ; $42FA
.setStatus
    inc de                                  ; $42FC
    pop hl                                  ; $42FD
    ld [hli],a                              ; $42FE
.savePtr
    ld a,e                                  ; $42FF
    ld [hli],a                              ; $4300
    ld a,d                                  ; $4301
    ld [hli],a                              ; $4302
    ld a,[wSndTrackIndex]                   ; $4303
    cp $05                                  ; $4306
    ret nc                                  ; $4308
    inc a                                   ; $4309
    ld [wSndTrackIndex],a                   ; $430A
    ld a,l                                  ; $430D
    add a,$1B                               ; $430E
    ld l,a                                  ; $4310
    jp SndTrackLoop                         ; $4311

; Commands $E0-$FF
SndParseCmd:
    cp $FF                                  ; $4314
    jp c,.notEnd                            ; $4316
    pop hl                                  ; $4319  $FF: end of track
    ld a,$04                                ; $431A
    ld [hl],a                               ; $431C
    jp SndNextTrack.noPop                   ; $431D
; $E0 n: loop start. Pushes a 4-byte frame (pass = 1, n, return address).
.notEnd
    cp $E0                                  ; $4320
    jp nz,.notLoopStart                     ; $4322
    push hl                                 ; $4325
    ld a,l                                  ; $4326
    add a,$0C                               ; $4327
    ld l,a                                  ; $4329
    ld a,[hl]                               ; $432A
    inc a                                   ; $432B
    ld [hli],a                              ; $432C
    dec a                                   ; $432D
    sla a                                   ; $432E
    sla a                                   ; $4330
    add a,l                                 ; $4332
    ld l,a                                  ; $4333
    ld a,$01                                ; $4334
    ld [hli],a                              ; $4336
    inc de                                  ; $4337
    ld a,[de]                               ; $4338
    ld [hli],a                              ; $4339
    inc de                                  ; $433A
    ld a,e                                  ; $433B
    ld [hli],a                              ; $433C
    ld a,d                                  ; $433D
    ld [hli],a                              ; $433E
    pop hl                                  ; $433F
    jp SndParse                             ; $4340
; $E1: loop end. pass += 1; repeat while pass <= n.
.notLoopStart
    cp $E1                                  ; $4343
    jp nz,.notLoopEnd                       ; $4345
    push hl                                 ; $4348
    ld a,l                                  ; $4349
    add a,$0C                               ; $434A
    ld l,a                                  ; $434C
    ld a,[hli]                              ; $434D
    dec a                                   ; $434E
    sla a                                   ; $434F
    sla a                                   ; $4351
    add a,l                                 ; $4353
    ld l,a                                  ; $4354
    inc [hl]                                ; $4355
    ld a,[hli]                              ; $4356
    ld b,a                                  ; $4357
    ld a,[hli]                              ; $4358
    ; n = 0: loop forever (Doraemon only)
    and a                                   ; $4359
    jr z,.loopAgain                         ; $435A
    sub b                                   ; $435C
    jr c,.exitLoop                          ; $435D
.loopAgain
    ld a,[hli]                              ; $435F
    ld e,a                                  ; $4360
    ld a,[hl]                               ; $4361
    ld d,a                                  ; $4362
    pop hl                                  ; $4363
    jp SndParse                             ; $4364
.exitLoop
    inc de                                  ; $4367
.popLoop
    pop hl                                  ; $4368
    push hl                                 ; $4369
    ld a,l                                  ; $436A
    add a,$0C                               ; $436B
    ld l,a                                  ; $436D
    dec [hl]                                ; $436E
    pop hl                                  ; $436F
    jp SndParse                             ; $4370
; $E2 p: pass marker (alternate ending). Scans forward from the $E2
; itself to the first "$E2 p" whose p equals the current pass, and
; continues after it. If that pass is the last one, the loop frame is
; dropped (the last ending has no $E1).
.notLoopEnd
    cp $E2                                  ; $4373
    jp nz,.pan                              ; $4375
    push hl                                 ; $4378
    ld a,l                                  ; $4379
    add a,$0C                               ; $437A
    ld l,a                                  ; $437C
    ld a,[hli]                              ; $437D
    dec a                                   ; $437E
    sla a                                   ; $437F
    sla a                                   ; $4381
    add a,l                                 ; $4383
    ld l,a                                  ; $4384
    ld a,[hli]                              ; $4385
    ld b,a                                  ; $4386
    ld a,[hl]                               ; $4387
    ld c,a                                  ; $4388
.scan
    ld a,[de]                               ; $4389
    inc de                                  ; $438A
    cp $E2                                  ; $438B
    jr nz,.scanNotPass                      ; $438D
    ld a,[de]                               ; $438F
    inc de                                  ; $4390
    cp b                                    ; $4391
    jr z,.found                             ; $4392
    jr .scan                                ; $4394
.scanNotPass
    cp $E0                                  ; $4396
    jr c,.scanRow                           ; $4398
    cp $E1                                  ; $439A
    jr z,.scan                              ; $439C
    inc de                                  ; $439E
    jr .scan                                ; $439F
.scanRow
    cp $D0                                  ; $43A1
    jr c,.scanNoteByte                      ; $43A3
    inc de                                  ; $43A5
    inc de                                  ; $43A6
.scanNoteByte
    and $0F                                 ; $43A7
    cp $06                                  ; $43A9
    jr nz,.scan                             ; $43AB
    inc de                                  ; $43AD
    jr .scan                                ; $43AE
.found
    ld a,b                                  ; $43B0
    cp c                                    ; $43B1
    jr z,.popLoop                           ; $43B2
    pop hl                                  ; $43B4
    jp SndParse                             ; $43B5
; any other command ($E3-$EF, $F1-$FD) xx: NR51 = xx (global pan),
; written by the next SndOutput.
.pan
    inc de                                  ; $43B8
    ld a,[de]                               ; $43B9
    inc de                                  ; $43BA
    ld [wSndPan],a                          ; $43BB
    ld a,$01                                ; $43BE
    ld [wSndPanFlag],a                      ; $43C0
    jp SndParse                             ; $43C3

; No new row this tick: run the instrument envelope (only while a
; note is sounding, status 2).
SndTrackEnvelope:
    ld a,c                                  ; $43C6
    cp $02                                  ; $43C7
    jp nz,SndNextTrack                      ; $43C9
    ld a,l                                  ; $43CC
    add a,$06                               ; $43CD
    ld l,a                                  ; $43CF
    ld a,[hli]                              ; $43D0
    and a                                   ; $43D1
    jp z,SndNextTrack                       ; $43D2
    cp $01                                  ; $43D5
    jp nz,.notVolSteps                      ; $43D7
    ; mode 1: every TRK_ENVPARAM frames, the next volume step goes to the
    ; NRx2 high nibble and the note is retriggered (status 6).
    inc l                                   ; $43DA
    ld a,[hl]                               ; $43DB
    dec a                                   ; $43DC
    ld [hld],a                              ; $43DD
    jp nz,SndNextTrack                      ; $43DE
    ld a,[hli]                              ; $43E1
    ld [hli],a                              ; $43E2
    ld a,[hli]                              ; $43E3
    ld e,a                                  ; $43E4
    ld a,[hli]                              ; $43E5
    ld d,a                                  ; $43E6
    ld a,[hl]                               ; $43E7
    add a,e                                 ; $43E8
    ld e,a                                  ; $43E9
    jr nc,.l43ED                            ; $43EA
    inc d                                   ; $43EC
.l43ED
    ld a,[hl]                               ; $43ED
    cp $07                                  ; $43EE
    jr nc,.l43F3                            ; $43F0
    inc [hl]                                ; $43F2
.l43F3
    ld a,[de]                               ; $43F3
    ld b,a                                  ; $43F4
    ld a,l                                  ; $43F5
    sub $08                                 ; $43F6
    ld l,a                                  ; $43F8
    ld a,[hl]                               ; $43F9
    and $0F                                 ; $43FA
    swap b                                  ; $43FC
    or b                                    ; $43FE
    ld [hl],a                               ; $43FF
    jp .retrigger                           ; $4400
; mode 2: decrements the counter, but "dec" leaves carry clear after the
; "cp $02", so "jp nc" is always taken and the note is never released.
.notVolSteps
    cp $02                                  ; $4403
    jr nz,.gateCount                        ; $4405
    inc l                                   ; $4407
    ld a,[hl]                               ; $4408
    dec a                                   ; $4409
    ld [hld],a                              ; $440A
    jp nc,SndNextTrack                      ; $440B
    ld a,$05                                ; $440E
    jr .store                               ; $4410
; mode 3: gate countdown -= tempo; on underflow, release (status 5).
; This cuts the note about n frames before its row ends.
.gateCount
    inc l                                   ; $4412
    inc l                                   ; $4413
    ld a,[wSndTrackIndex]                   ; $4414
    cp $04                                  ; $4417
    jr nc,.l4420                            ; $4419
    ld a,[wSndMusicTempo]                   ; $441B
    jr .l4423                               ; $441E
.l4420
    ld a,[wSndSfxTempo]                     ; $4420
.l4423
    ld b,a                                  ; $4423
    ld a,[hl]                               ; $4424
    sub b                                   ; $4425
    ld [hli],a                              ; $4426
    ld a,[hl]                               ; $4427
    sbc a,$00                               ; $4428
    ld [hl],a                               ; $442A
    jr nc,SndNextTrack                      ; $442B
    ld a,$05                                ; $442D
    jr .store                               ; $442F
.retrigger
    ld a,$06                                ; $4431
.store
    pop hl                                  ; $4433
    ld [hl],a                               ; $4434
    ld a,[wSndTrackIndex]                   ; $4435
    cp $05                                  ; $4438
    ret nc                                  ; $443A
    inc a                                   ; $443B
    ld [wSndTrackIndex],a                   ; $443C
    ld a,l                                  ; $443F
    add a,$1E                               ; $4440
    ld l,a                                  ; $4442
    jp SndTrackLoop                         ; $4443
SndNextTrack:
    pop hl                                  ; $4446
.noPop
    ld a,[wSndTrackIndex]                   ; $4447
    cp $05                                  ; $444A
    ret nc                                  ; $444C
    inc a                                   ; $444D
    ld [wSndTrackIndex],a                   ; $444E
    ld a,l                                  ; $4451
    add a,$1E                               ; $4452
    ld l,a                                  ; $4454
    jp SndTrackLoop                         ; $4455

; SndOutput: writes the registers decided by the last SndUpdate.
; Status after SndUpdate: 6 = key on, 5 = release, 4 = ending.
; Each is reduced by 4 here (2 = sounding, 1 = released, 0 = off).
SndOutput:
    ld a,[wSndSfxTracks]                    ; $4458
    and a                                   ; $445B
    jp nz,SndOutputWithSfx                  ; $445C
    ld a,[wSndPanFlag]                      ; $445F
    cp $01                                  ; $4462
    jr nz,.ch1                              ; $4464
    ld a,$00                                ; $4466
    ld [wSndPanFlag],a                      ; $4468
    ld a,[wSndPan]                          ; $446B
    ldh [rNR51],a                           ; $446E
.ch1
    ld a,[wSndCh1]                          ; $4470
    sub $04                                 ; $4473
    jr c,.ch2                               ; $4475
    ld [wSndCh1],a                          ; $4477
    cp $02                                  ; $447A
    jr z,.ch1Write                          ; $447C
    cp $01                                  ; $447E
    jr z,.ch1Release                        ; $4480
    ; ending: silence the channel, one track fewer; at 0 the song is over
    ld a,$08                                ; $4482
    ldh [rNR12],a                           ; $4484
    ld a,$80                                ; $4486
    ldh [rNR14],a                           ; $4488
    ld a,[wSndMusicTracks]                  ; $448A
    dec a                                   ; $448D
    ld [wSndMusicTracks],a                  ; $448E
    jr nz,.ch2                              ; $4491
    ld a,$FF                                ; $4493
    ld [wSndMusicId],a                      ; $4495
    jr .ch2                                 ; $4498
; release: NRx2 keeps only its low nibble (volume 0) + retrigger
.ch1Release
    ld a,[wSndCh1 + TRK_NR2]                ; $449A
    and $0F                                 ; $449D
    ldh [rNR12],a                           ; $449F
    ld a,[wSndCh1 + TRK_NR4]                ; $44A1
    ldh [rNR14],a                           ; $44A4
    jr .ch2                                 ; $44A6
.ch1Write
    ld hl,wSndCh1 + TRK_NR0                 ; $44A8
    ld c,$10                                ; $44AB
    ld a,[hli]                              ; $44AD
    ldh [c],a                               ; $44AE
    inc c                                   ; $44AF
    ld a,[hli]                              ; $44B0
    ldh [c],a                               ; $44B1
    inc c                                   ; $44B2
    ld a,[hli]                              ; $44B3
    ldh [c],a                               ; $44B4
    inc c                                   ; $44B5
    ld a,[hli]                              ; $44B6
    ldh [c],a                               ; $44B7
    inc c                                   ; $44B8
    ld a,[hl]                               ; $44B9
    ldh [c],a                               ; $44BA
.ch2
    ld a,[wSndCh2]                          ; $44BB
    sub $04                                 ; $44BE
    jr c,.ch3                               ; $44C0
    ld [wSndCh2],a                          ; $44C2
    cp $02                                  ; $44C5
    jr z,.ch2Write                          ; $44C7
    cp $01                                  ; $44C9
    jr z,.ch2Release                        ; $44CB
    ld a,$08                                ; $44CD
    ldh [rNR22],a                           ; $44CF
    ld a,$80                                ; $44D1
    ldh [rNR24],a                           ; $44D3
    ld a,[wSndMusicTracks]                  ; $44D5
    dec a                                   ; $44D8
    ld [wSndMusicTracks],a                  ; $44D9
    jr nz,.ch3                              ; $44DC
    ld a,$FF                                ; $44DE
    ld [wSndMusicId],a                      ; $44E0
    jr .ch3                                 ; $44E3
.ch2Release
    ld a,[wSndCh2 + TRK_NR2]                ; $44E5
    and $0F                                 ; $44E8
    ldh [rNR22],a                           ; $44EA
    ld a,[wSndCh2 + TRK_NR4]                ; $44EC
    ldh [rNR24],a                           ; $44EF
    jr .ch3                                 ; $44F1
.ch2Write
    ld hl,wSndCh2 + TRK_NR1                 ; $44F3
    ld c,$16                                ; $44F6
    ld a,[hli]                              ; $44F8
    ldh [c],a                               ; $44F9
    inc c                                   ; $44FA
    ld a,[hli]                              ; $44FB
    ldh [c],a                               ; $44FC
    inc c                                   ; $44FD
    ld a,[hli]                              ; $44FE
    ldh [c],a                               ; $44FF
    inc c                                   ; $4500
    ld a,[hl]                               ; $4501
    ldh [c],a                               ; $4502
.ch3
    ld a,[wSndCh3]                          ; $4503
    sub $04                                 ; $4506
    jr c,.ch4                               ; $4508
    ld [wSndCh3],a                          ; $450A
    cp $02                                  ; $450D
    jr z,.ch3Write                          ; $450F
    cp $01                                  ; $4511
    jr z,.ch3Release                        ; $4513
    ld a,$00                                ; $4515
    ldh [rNR30],a                           ; $4517
    ld a,[wSndMusicTracks]                  ; $4519
    dec a                                   ; $451C
    ld [wSndMusicTracks],a                  ; $451D
    jr nz,.ch4                              ; $4520
    ld a,$FF                                ; $4522
    ld [wSndMusicId],a                      ; $4524
    jr .ch4                                 ; $4527
.ch3Release
    ld a,$00                                ; $4529
    ldh [rNR30],a                           ; $452B
    jr .ch4                                 ; $452D
; ch3 key on: if ch3 is already running only the frequency is updated
; (no retrigger). Otherwise NR31-NR34 are written with NR30 = $80.
.ch3Write
    ldh a,[rNR52]                           ; $452F
    and $04                                 ; $4531
    jr nz,.ch3Legato                        ; $4533
    ld hl,wSndCh3 + TRK_NR1                 ; $4535
    ld c,$1B                                ; $4538
    ld a,[hli]                              ; $453A
    ldh [c],a                               ; $453B
    inc c                                   ; $453C
    ld a,[hli]                              ; $453D
    ldh [c],a                               ; $453E
    inc c                                   ; $453F
    ld a,[hli]                              ; $4540
    ldh [c],a                               ; $4541
    inc c                                   ; $4542
    ld a,$80                                ; $4543
    ldh [rNR30],a                           ; $4545
    ld a,[hl]                               ; $4547
    ldh [c],a                               ; $4548
    jr .ch4                                 ; $4549
.ch3Legato
    ld a,[wSndCh3 + TRK_NR3]                ; $454B
    ldh [rNR33],a                           ; $454E
    ld a,[wSndCh3 + TRK_NR4]                ; $4550
    and $7F                                 ; $4553
    ldh [rNR34],a                           ; $4555
.ch4
    ld a,[wSndCh4]                          ; $4557
    sub $04                                 ; $455A
    ret c                                   ; $455C
    ld [wSndCh4],a                          ; $455D
    cp $02                                  ; $4560
    jr z,.ch4Write                          ; $4562
    cp $01                                  ; $4564
    jr z,.ch4Release                        ; $4566
    ld a,$08                                ; $4568
    ldh [rNR42],a                           ; $456A
    ld a,$80                                ; $456C
    ldh [rNR44],a                           ; $456E
    ld a,[wSndMusicTracks]                  ; $4570
    dec a                                   ; $4573
    ld [wSndMusicTracks],a                  ; $4574
    ret nz                                  ; $4577
    ld a,$FF                                ; $4578
    ld [wSndMusicId],a                      ; $457A
    ret                                     ; $457D
.ch4Release
    ld a,[wSndCh4 + TRK_NR2]                ; $457E
    and $0F                                 ; $4581
    ldh [rNR42],a                           ; $4583
    ld a,[wSndCh4 + TRK_NR4]                ; $4585
    ldh [rNR44],a                           ; $4588
    ret                                     ; $458A
.ch4Write
    ld hl,wSndCh4 + TRK_NR1                 ; $458B
    ld c,$20                                ; $458E
    ld a,[hli]                              ; $4590
    ldh [c],a                               ; $4591
    inc c                                   ; $4592
    ld a,[hli]                              ; $4593
    ldh [c],a                               ; $4594
    inc c                                   ; $4595
    ld a,[hli]                              ; $4596
    ldh [c],a                               ; $4597
    inc c                                   ; $4598
    ld a,[hl]                               ; $4599
    ldh [c],a                               ; $459A
    ret                                     ; $459B

; Same as SndOutput while an SFX runs. Music ch1/ch4 are held at
; status 1 (parsed but not written); hardware ch1/ch4 play the SFX.
; On the first frame NR51 gets $99 ORed in so ch1/ch4 are audible.
SndOutputWithSfx:
    ld a,[wSndPanFlag]                      ; $459C
    cp $01                                  ; $459F
    jr nz,.musCh1                           ; $45A1
    ld a,$00                                ; $45A3
    ld [wSndPanFlag],a                      ; $45A5
    ld a,[wSndPan]                          ; $45A8
    or $99                                  ; $45AB
    ldh [rNR51],a                           ; $45AD
.musCh1
    ld a,[wSndCh1]                          ; $45AF
    cp $04                                  ; $45B2
    jr z,.musCh1End                         ; $45B4
    and a                                   ; $45B6
    jr z,.sfxCh1                            ; $45B7
    ld a,$01                                ; $45B9
    ld [wSndCh1],a                          ; $45BB
    jr .sfxCh1                              ; $45BE
.musCh1End
    xor a                                   ; $45C0
    ld [wSndCh1],a                          ; $45C1
    ld a,[wSndMusicTracks]                  ; $45C4
    dec a                                   ; $45C7
    ld [wSndMusicTracks],a                  ; $45C8
    jr nz,.sfxCh1                           ; $45CB
    ld a,$FF                                ; $45CD
    ld [wSndMusicId],a                      ; $45CF
.sfxCh1
    ld a,[wSndSfxCh1]                       ; $45D2
    sub $04                                 ; $45D5
    jr c,.ch2                               ; $45D7
    ld [wSndSfxCh1],a                       ; $45D9
    cp $02                                  ; $45DC
    jr z,.sfxCh1Write                       ; $45DE
    cp $01                                  ; $45E0
    jr z,.sfxCh1Release                     ; $45E2
    ld a,$08                                ; $45E4
    ldh [rNR12],a                           ; $45E6
    ld a,$80                                ; $45E8
    ldh [rNR14],a                           ; $45EA
    ld a,[wSndSfxTracks]                    ; $45EC
    dec a                                   ; $45EF
    ld [wSndSfxTracks],a                    ; $45F0
    jr nz,.ch2                              ; $45F3
    ; SFX over: restore the music NR51 on the next SndOutput
    ld a,$01                                ; $45F5
    ld [wSndPanFlag],a                      ; $45F7
    ld a,$FF                                ; $45FA
    ld [wSndSfxId],a                        ; $45FC
    jr .ch2                                 ; $45FF
.sfxCh1Release
    ld a,[wSndSfxCh1 + TRK_NR2]             ; $4601
    and $0F                                 ; $4604
    ldh [rNR12],a                           ; $4606
    ld a,[wSndSfxCh1 + TRK_NR4]             ; $4608
    ldh [rNR14],a                           ; $460B
    jr .ch2                                 ; $460D
.sfxCh1Write
    ld hl,wSndSfxCh1 + TRK_NR0              ; $460F
    ld c,$10                                ; $4612
    ld a,[hli]                              ; $4614
    ldh [c],a                               ; $4615
    inc c                                   ; $4616
    ld a,[hli]                              ; $4617
    ldh [c],a                               ; $4618
    inc c                                   ; $4619
    ld a,[hli]                              ; $461A
    ldh [c],a                               ; $461B
    inc c                                   ; $461C
    ld a,[hli]                              ; $461D
    ldh [c],a                               ; $461E
    inc c                                   ; $461F
    ld a,[hli]                              ; $4620
    ldh [c],a                               ; $4621
.ch2
    ld a,[wSndCh2]                          ; $4622
    sub $04                                 ; $4625
    jr c,.ch3                               ; $4627
    ld [wSndCh2],a                          ; $4629
    cp $02                                  ; $462C
    jr z,.ch2Write                          ; $462E
    cp $01                                  ; $4630
    jr z,.ch2Release                        ; $4632
    ld a,$08                                ; $4634
    ldh [rNR22],a                           ; $4636
    ld a,$80                                ; $4638
    ldh [rNR24],a                           ; $463A
    ld a,[wSndMusicTracks]                  ; $463C
    dec a                                   ; $463F
    ld [wSndMusicTracks],a                  ; $4640
    jr nz,.ch3                              ; $4643
    ld a,$FF                                ; $4645
    ld [wSndMusicId],a                      ; $4647
    jr .ch3                                 ; $464A
.ch2Release
    ld a,[wSndCh2 + TRK_NR2]                ; $464C
    and $0F                                 ; $464F
    ldh [rNR22],a                           ; $4651
    ld a,[wSndCh2 + TRK_NR4]                ; $4653
